  str_n7_mission_title_12 = "ST2 - Sombras",
  str_n7_mission_desc_2 = "Você segue para Umbraton, a cidade envolta em sombras, depois de receber a carta.",
  str_n7_mission_desc_3 = "Depois de se encontrar com Bethel, você chega à sede da guilda para se preparar para a entrega dos ativos Caelestite.",
  str_n7_mission_desc_4 = "A sede está sob ataque Eclipsite? O que está acontecendo...?",
  str_n7_mission_desc_5 = "Sem pistas, Luke propõe que você tente a sorte no Crossroads Bar.",
  str_n7_mission_desc_6 = "A investigação está parada. Você decide ir ao leilão clandestino primeiro com Luke.",
  str_n7_mission_desc_7 = "Rhein traiu o Shadowlord? Você tem que encontrar Betel e informá-la imediatamente!",
  str_n7_mission_desc_8 = "Betel também foi atacada, como você temia. Parece que uma rebelião está se formando em Umbraton...",
  str_n7_mission_desc_9 = "Ao ouvir que as outras guildas principais também foram atacadas, você decide fornecer suporte imediatamente.",
  str_n7_mission_desc_10 = "Depois de receber mais orientações, você chega à sede da Steelfire Gang. Parece que os chefes das principais guildas estão sendo mantidos aqui...",
  str_n7_mission_desc_11 = "Rhein e Maude provavelmente estão atacando a represa neste exato momento. Vá para a Represa das Cicatrizes imediatamente!",
  str_n7_mission_desc_long_1 = "Você recebeu uma carta de Umbraton convidando-o a assumir os bens deixados pelos Caelestitas.\nNaroxel também ouviu falar que um item único conhecido como componente da sala de simulação está sendo leiloado no subsolo de Umbraton...",
  str_n7_mission_desc_long_2 = "Esta é \"A cidade envolta em sombras\".\nVocê se encontrou com o chefe da guilda, Bethel, mas os Eclipsites o atacaram inesperadamente em seu caminho para Umbraton.\nFelizmente, Luke, o comandante de um esquadrão de mercenários local, apareceu a tempo e decidiu acompanhá-lo.",
  str_n7_mission_desc_long_3 = "Quando você chega à guilda e se prepara para os procedimentos de transferência, outro ataque de Eclipsite ocorre.\nDado que esta é uma área tão bem protegida, isso pode realmente ser uma coincidência?",
  str_n7_mission_desc_long_4 = "Acontece que Pittman também veio a Umbraton para investigar os misteriosos Enhancers, e assim você ganhou outro aliado.\nNa esperança de encontrar mais pistas, Luke decide levá-lo a algum lugar...",
  str_n7_mission_desc_long_5 = "Você encontra Rhein da Blue Lion Guild no Crossroads Bar, junto com outra pessoa misteriosa.\nEles conseguem obstruir sua missão e, em vez de encontrar pistas úteis, você se vê novamente sob ataque.\nParece também que Betel saiu com muita pressa...",
  str_n7_mission_desc_long_6 = "Incapaz de prosseguir com sua investigação, você e Luke vão à casa de leilões para procurar os componentes da sala de simulação, mas você encontra Rhein e seus companheiros novamente.\nDesta vez, eles assumem o lugar rapidamente e sem piedade, e fazem um anúncio: Istvan está morto.",
  str_n7_mission_desc_long_7 = "Depois de sair do leilão, você corre para a guilda para encontrar Bethel.\nVocê encontra Bethel na sede e enfrentando o assassinato. Felizmente, tudo parece estar sob controle por enquanto.",
  str_n7_mission_desc_long_8 = "Seu pior medo se tornou realidade - Rhein de fato incitou a rebelião, e os homens de Betel também estão entre os traidores.\nQuanto ao Shadowlord, todos se recusam a acreditar que ele está morto.\nSua principal prioridade agora é ajudar as outras guildas sob ataque e acabar com o caos...",
  str_n7_mission_desc_long_9 = "Ao chegar na Lin Guild atacada, parece que alguém já ajudou a resolver a situação.\nLuke também fica ciente de uma nova pista e leva você ao seu próximo destino: a sede da Steelfire Gang.",
  str_n7_mission_desc_long_10 = "Você chega à sede da Steelfire Gang e resgata os líderes da guilda que foram sequestrados no leilão.\nIstvan Gang finalmente faz uma aparição inesperada e começa a manter a ordem.\nSeu próximo passo agora é perseguir o perpetrador por trás de tudo isso na Represa das Cicatrizes!",
  str_n7_mission_desc_long_11 = "Com seus planos frustrados, a enfurecida Maude engole os Enhancers.\nSob a presença dominante do Shadowlord, você sai vitorioso e a verdade é finalmente revelada.",
  str_n7_mission_desc_long_12 = "Muitas perguntas sobre este assunto permanecem sem resposta... Pittman também decide continuar sua investigação.\nVocê obtém o componente da sala de simulação para o qual veio, que pode ser de grande utilidade no futuro...",
  str_n7_paper_1_1_title = "<size=40><color=#353330>Rugindo Leões Azuis!\nRecompensas duplas da Arena Subterrânea anunciadas!</color></size>",
  str_n7_paper_1_2_title = [[
<size=35>Uma entrevista com 
O Senhor das Sombras</size>]],
  str_n7_paper_1_3_title = "<size=30><color=#353330>Enciclopédia Eclipsita #50\nO Último Celestita</color></size>",
  str_n7_paper_1_4_title = "<size=30><color=#353330>Biscates Promoção Jumbo para a Estação das Chuvas</color></size>",
  str_n7_paper_1_5_title = "<size=30><color=#353330>Miller III pega o dinheiro e foge!\nLoja de prestígio oferece preço de pechincha!</color></size>",
  str_n7_paper_2_1_title = "<size=40><color=#353330>Uma tempestade se aproxima!\nBrilhem, estrelas da Arena Subterrânea!</color></size>",
  str_n7_paper_2_2_title = "<size=40>Salão Misty\nBanquete da Alta Sociedade</size>",
  str_n7_paper_2_3_title = "<size=35><color=#353330>gato perdido</color></size>",
  str_n7_paper_2_4_title = "<size=30><color=#353330>Novo Serviço de Decoração Courier Union!</color></size>",
  str_n7_paper_2_5_title = "<size=30><color=#353330>A Lin Guild fecha temporariamente</color></size>",
  str_n7_paper_3_1_title = "<size=32><color=#353330>Triunfo Celestita na Arena Subterrânea de Surpresa!\nA salvação está à mão para uma loja centenária?</color></size>",
  str_n7_paper_3_2_title = [[
<size=40>Livre significa lucro?
Lady Sheol Entrevista!</size>]],
  str_n7_paper_3_3_title = "<size=30><color=#353330>Estranhos Eclipsites Avistados\nEm São João Confiamos</color></size>",
  str_n7_paper_3_4_title = "<size=30><color=#353330>Paz em Umbraton?\nRumores de titãs da indústria para acabar com o conflito</color></size>",
  str_n7_paper_3_5_title = "<size=35><color=#353330>Gangues de fofocas</color></size>",
  str_n7_paper_4_1_title = "<size=38><color=#353330>Newsflash: Blue Lions Bare Fangs!\nRhein é suspeito de atacar a represa!</color></size>",
  str_n7_paper_4_2_title = "<size=35>cavalo escuro\nSupera as probabilidades de reivindicar a vitória</size>",
  str_n7_paper_4_3_title = "<size=35><color=#353330>Spearows ganha prêmio de segurança pública novamente</color></size>",
  str_n7_paper_4_4_title = "<size=30><color=#353330>Leilões clandestinos de classe alta são proibidos\nMantido secretamente por anos como \"salão\"</color></size>",
  str_n7_paper_4_5_title = "<size=30><color=#353330>Cadáver de Eclipsite jogado à vista de todos\nSuspeita de envolvimento do Tribunal de Justiça</color></size>",
  str_n7_paper_5_1_title = "<size=50><color=#353330>Todos saúdam o poderoso celestita\nSalve as Amizades!</color></size>",
  str_n7_paper_5_2_title = "<size=30>Sede da Guilda avança\nLeilões clandestinos retornarão</size>",
  str_n7_paper_5_3_title = "<size=35><color=#353330>Recrutamento de Mercenários da Chama Branca</color></size>",
  str_n7_paper_5_4_title = "<size=30><color=#353330>Últimas notícias! Phantom Wandering Umbraton Streets Identificado!</color></size>",
  str_n7_paper_5_5_title = "<size=30><color=#353330>Guilda do Leão Azul Enfrenta o Fim\nFamília Solus Desaparecida</color></size>",
  str_n7_paper_1_1_content = "<size=35><color=#353330>Graças às significativas contribuições financeiras do Sr. Rhein da Blue Lion Guild, uma montanha de Nightium agora aguarda o vencedor do próximo torneio Underground Arena. Em resposta aos muitos agradecimentos dos organizadores, Rhein afirma que esta contribuição foi apenas um dia de renda para os Blue Lions, os lendários gigantes comerciais de Umbraton.\nA Underground Arena recebe esse nome não pelo fato de ser realizada abaixo da superfície da cidade, mas por causa de suas regras, ou melhor, pelo fato de não haver regras. O vencedor pode dormir sobre um monte de ouro, enquanto os perdedores... não precisarão mais se preocupar com o futuro. Muitos dos lutadores menos valentes da cidade já foram dissuadidos. No entanto, com a enorme premiação deste ano, todo lutador se tornou um candidato da noite para o dia. O escritório de registro tem sido sobrecarregado com desafiadores todos os dias. Alguns até começaram brigas de rua para se aquecer para o evento.\nCom esta grande ocasião, o organizador mais uma vez agradeceu a Rhein por sua ajuda, enquanto o respeitado Rhein disse: \"Não me agradeça. Eu deveria estar agradecendo pela paixão que você demonstrou pela Underground Arena. Tenho o prazer de veja a empolgação que a Underground Arena gerou enquanto enfrentamos esses dias sombrios. Não importa se você ganha o prêmio ou não, espero que todos em Umbraton possam esquecer seus problemas e aproveitar completamente a emoção da Underground Arena.\"\nNão se pode deixar de elogiar Rhein por sua abnegação e amor pela Underground Arena. Que o Blue Lion Guild prospere e continue apoiando o evento por muitos anos!\n </color></size>",
  str_n7_paper_1_2_content = "<size=35><color=#353330>Istvan foi visto vagando no deserto fora de Umbraton recentemente, cada vez em um local diferente. Felizmente, nosso repórter aprimorou suas habilidades de rastreamento no exército e foi coroado campeão da maratona anual de evacuação do campo de batalha. Ele finalmente encontrou o Shadowlord no vale do norte de Umbraton - acontece que Istvan é na verdade um homem muito misterioso e encantador!\nNosso repórter não poupou esforços para rastrear Istvan para pedir sua opinião sobre o investimento da Blue Lion Guild na Underground Arena. O Shadowlord respondeu: \"Eu estarei assistindo.\"\nComo todos sabemos, Istvan sempre se inclinou para proibir tais competições. Portanto, muitos especuladores acreditam que o investimento significativo da Blue Lion Guild na Underground Arena é um desafio direto à autoridade de Istvan. De acordo com as notícias anteriores, Istvan deve competir pelo controle da Underground Arena. No entanto, depois de ouvir a resposta de Istvan, os comerciantes agora acreditam que o Shadowlord tem assuntos mais importantes em mente, levando-os a comprar um grande número de títulos da Blue Lion Guild.</color></size>",
  str_n7_paper_1_3_content = "<size=28><color=#353330>Dezessete anos atrás, Eraveil foi destruído, e apenas alguns Caelestites, inimigos mortais dos Eclipsites, foram deixados vivos. Os celestitas possuíam poderosas habilidades psíquicas e podiam até afetar o coração dos outros. Alguns dizem que os celestitas poderiam até mesmo transformar os aurorianos em eclipsitas.\nFoi relatado que o último celestita chegou a Umbraton com motivos ainda desconhecidos. Recomenda-se que todos os residentes de Umbraton prestem atenção especial à segurança pessoal em todos os momentos. Se você vir o Celestita, por favor, mantenha distância para evitar ser possuído psiquicamente ou transformado em um Eclipsite.</color></size>",
  str_n7_paper_1_4_content = "<size=28><color=#353330>A estação das chuvas está chegando. Você já se viu lutando para secar suas roupas? Para além dos muitos outros serviços de cumprimento da lei que tem para lhe oferecer, a Odd Jobs, a loja que garante sempre a sua satisfação, acaba de lançar um novo Serviço de Secagem Luminatics! Seja uma camisa, casaco, peles, lenços de malha ou até mesmo uma nova bolsa de couro de marca, Taki usará seus Luminatics quentes e calorosos para infundir seus pertences com uma fragrância única e secá-los rapidamente. Cheire-os e encha seu coração com a luz do sol - respire seu aroma perfumado e abrace a vitalidade do verão eterno!\nServiços gratuitos de recuperação de dívidas para cinquenta roupas em um recibo. (Gangues de mais de 100 membros como devedor estarão sujeitas a taxas adicionais.)</color></size>",
  str_n7_paper_1_5_content = "<size=28><color=#353330>A Miller Guild, com sua loja Umbraton centenária, é famosa por seu serviço de revenda profissional e de alta qualidade. Devido à situação cada vez mais caótica da segurança pública em Umbraton recentemente, a maioria dos criminosos tem usado meios não convencionais e não regulamentados para vender mercadorias roubadas. Alguns até vendem seus produtos roubados na rua, iniciando guerras de preços que resultaram em uma diminuição significativa no faturamento da Miller Guild. A fim de salvar a guilda da ruína, Miller III, o líder da guilda, rapidamente se voltou para o jogo e, após contrair enormes dívidas de jogo, ele parece ter fugido e não foi encontrado em lugar nenhum.\nAgora, a Gambling Union confiou a este jornal o direito de vender a licença de revenda de bens ilícitos da Miller Guild a um preço especial. De acordo com fontes confiáveis, as principais gangues de Umbraton realizarão uma operação conjunta em breve para reforçar a segurança pública em Umbraton e prender comerciantes de mercadorias ilegais. Espera-se que esta operação resolva o principal problema de falha nos negócios da Miller Guild.</color></size>",
  str_n7_paper_2_1_content = "<size=35><color=#353330>O torneio Underground Arena está bem encaminhado, e a ferocidade dos contendores começou a se espalhar para fora do ringue e para as ruas, já que vários desafiantes populares foram descobertos nos becos da cidade, neutralizados por seus colegas competidores. Os duelos ferozes dos últimos dias trouxeram vários lutadores com habilidades únicas à tona, incluindo o mais emocionante e popular lutador cabeça-de-chave, Becker, promovido com sucesso para a próxima rodada. Poucos podem esquecer o momento em que ele destruiu as maçanetas de metal dos portões da arena. Claro, Becker é mais do que apenas um showman carismático - até agora, ele também destruiu todos os seus oponentes. Isso mesmo, destruído, não apenas derrotado - todos os desafortunados o suficiente para enfrentar Becker estão agora deitados na mesma sala do Umbraton General Hospital e não poderão mais competir neste torneio.\nDe acordo com o cronograma do torneio, as preocupações agora envolvem o próximo adversário de Becker. Há rumores de que o recém-chegado desconhecido é o único sobrevivente dos Caelestitas. Embora todos esperemos ver uma batalha magnífica, também esperamos que o corpo frágil possa suportar os sólidos punhos de aço de Becker!\nClaro, esta enorme diferença de força não significa que o resultado desta batalha já é uma conclusão precipitada! Segundo a pesquisa, os hábitos de vida convencionais podem restringir seriamente o desenvolvimento do corpo, especialmente em termos de dieta. Portanto, gostaríamos de apresentar a você o Power Punch Protein Powder, desenvolvido pela Blue Lion Guild! Reduza sua dose diária para alcançar novos patamares de condicionamento físico! O desafiante estrela Becker é o primeiro guerreiro a experimentar este produto, e sua eficácia agora é óbvia para qualquer um que tenha acompanhado o torneio. Entre em contato conosco diretamente para comprar Power Punch Protein Powder hoje!\n</color></size>",
  str_n7_paper_2_2_content = "<size=35><color=#353330>Os escalões superiores da sociedade Umbraton e celebridades de todos os círculos aguardam um convite para este raro salão exclusivo e banquete com grande expectativa. Este salão da alta sociedade existe em Umbraton há muitos anos, nos tempos difíceis e bons. Desde a sua criação, tem servido aos prazeres da elite e celebridades de todos os tipos, com o objetivo de guiar a Umbraton para um futuro melhor e mais próspero por meio da troca de ideias entre pessoas de diversas áreas.\nOs organizadores exibirão novas obras de arte no próximo salão, incluindo Mountain Roots, The Fish's Breath, Paw Print e Empty Wisdom. Celebridades da Umbraton de todas as áreas foram convidadas para discutir arte juntas, e os organizadores estão ansiosos por suas valiosas avaliações.\nDesejamos aos organizadores e participantes do salão uma noite produtiva e agradecemos aos organizadores pelo generoso patrocínio a este jornal.</color></size>",
  str_n7_paper_2_3_content = "<size=28><color=#353330>Meu gato está desaparecido - palavras não podem expressar o quanto é importante para mim! Você pode por favor me ajudar? Se meu gato for devolvido em segurança, você terá meus agradecimentos e até mesmo lhe darei cinquenta xícaras de café como recompensa!\nSobre o My Cat: É um pequeno gato mecânico preto, muito realista, mas com fiação mecânica óbvia visível na seção danificada de sua pata dianteira esquerda. Ele tem uma fita vermelha em volta do pescoço com um crachá de latão preso a ele.\nAlém disso, seus olhos são de cores diferentes, e é lindo!\nSe você tiver alguma informação, entre em contato com Connolly, proprietário do Holiday Café. Muito obrigado!</color></size>",
  str_n7_paper_2_4_content = "<size=28><color=#353330>A Courier Union, prestadora de serviços profissionais de renome mundial, acredita na prestação de serviços de classe mundial a todas as pessoas que amam a paz em Astra. E agora, após vários meses de preparação, a Courier Union está pronta para lançar um novo serviço de decoração! Quer viva num quarto individual ou numa mansão, a equipa de decoração da Courier Union pode fornecer-lhe uma gama completa de serviços desde a concepção e aquisição até à construção e avaliação. Prometemos que, se o serviço não atingir o efeito desejado, a redecoração é gratuita!\nSe encomendar serviços de decoração através do nosso jornal, pode poupar 50 Nightium extra para além do seu desconto de 20%! Este evento é limitado apenas a este mês, então certifique-se de fazer seu pedido o mais rápido possível! Entre em contato com o representante da Umbraton, Eho, para mais detalhes!</color></size>",
  str_n7_paper_2_5_content = "<size=28><color=#353330>Várias lojas pertencentes ao The Lin Guild foram fechadas, com o tempo de reabertura ainda determinado.\nRecentemente, conduzimos uma investigação no local sobre os rumores sobre o fechamento de várias lojas pertencentes ao The Lin Guild. Agora podemos relatar que essas lojas foram realmente fechadas. Esses fechamentos não foram anunciados com antecedência, resultando em perdas significativas para muitos de seus clientes. Aqueles familiarizados com este assunto suspeitam que a família Lin esteja planejando uma conspiração, mas exatamente quando essas lojas voltarão a funcionar é completamente desconhecido.</color></size>",
  str_n7_paper_3_1_content = "<size=35><color=#353330>\"O celestita é mais parecido com uma galinha do que com um companheiro de equipe\", gritou Becker antes da partida.\nNo entanto, nunca se pode ter muita certeza no calor da competição. Sob o comando do Celestita, toda a equipe se moveu como o vento, coordenou perfeitamente e atacou ferozmente. Se Becker não tivesse parado o jogo nocauteando acidentalmente o juiz no meio da luta, ele teria caído na primeira rodada de ataques.\nApós o reinício da partida, Becker se esquivou antes da vez do celestita para atacar, mas de repente gritou de dor e caiu no chão, espumando pela boca. Ele então começou a tremer e logo foi levado para fora do campo de batalha. De acordo com o médico no local, Becker parece ter sido solicitado pelo patrocinador para tomar Power Punch Protein Powder no meio da competição. Isso levou a cólicas abdominais e desencadeou um espasmo muscular abdominal induzido pelo estresse, forçando-o a engolir a amargura da derrota. Alguns também dizem que o celestita viu que Becker estava tendo problemas para lutar e usou alguns truques desleais para causar cãibras em Becker. Seja qual for a verdade, essa emergência causou pânico entre muitos concorrentes que usam o mesmo produto.\nNosso repórter afirmou que o silêncio tomou conta da arena após a vitória inesperada do celestita. A única pessoa que começou a rir tão loucamente quanto Becker antes da luta foi Miller III. Acontece que, em seu desespero, ele apostou tudo o que tinha no celestita. As probabilidades ultrajantes antes da partida lhe renderam uma grande fortuna, e ele então exclamou: \"O Miller Guild está pronto para vender de volta todos os bens roubados pendentes!\"\n </color></size>",
  str_n7_paper_3_2_content = "<size=35><color=#353330>Repórter: Olá, Senhora Sheol. A Cloudrover Guild começou recentemente uma propaganda que diz \"pacote de presente grátis\". Todo o Umbraton está delirando sobre isso, já que o dinheiro cresce nas árvores. Você pode nos contar sobre a lógica por trás dessa mudança de negócios?\nSheol: Claro. Em primeiro lugar, obrigado por apoiar o Cloudrover Guild. A ideia por trás disso era mostrar nossa gratidão. É por isso que a guilda decidiu fornecer a todos esses pacotes de presentes.\nRepórter: Muitos investidores acreditam que esse movimento da Cloudrover Guild levará a perdas. No entanto, os resultados os deixaram sem palavras - a receita da Cloudrover Guild aumentou! Você pode nos dizer por quê?\nSheol: Fortalecemos a imagem pública da Cloudrover Guild. Como resultado, atualizaremos ainda mais os pacotes de presente para \"Gift Packs—Plus\"! Cada residente de Umbraton receberá um de graça, sem nenhuma condição adicional anexada!\nConclusão: Glória à Guilda Cloudrover! Embora estejam distribuindo pacotes de presentes, muitas pessoas foram inspiradas a gastar ainda mais depois de abrir os seus. Um fluxo interminável de pessoas tem inundado a Cloudrover Guild para comprar mais de seus produtos. Agora, é hora dos repórteres pegarem seu pacote de presentes!</color></size>",
  str_n7_paper_3_3_content = "<size=28><color=#353330>Ontem, um grupo de Eclipsites mutantes atacou repentinamente vários caminhões. Esses Eclipsites escondidos nas sombras exibiam formas estranhas e poder infinito. Eles podem ter sido resultados experimentais de algum cientista maluco desconhecido de Lumopolis. Nosso Umbraton está agora sob ameaças duplas de Lumopolis e Eclipsites aprimorados!\nDurante o ataque, alguém sabiamente borrifou o pó de erradicação do Eclipsita de São João nos Eclipsitos. Os eclipsitas imediatamente cobriram seus rostos e gritaram enquanto fugiam. Todos os presentes sobreviveram.\nO pó de erradicação de Eclipsite de São João é feito através de 88 processos elaborados e é um medicamento essencial para qualquer pessoa, tanto em casa quanto fora, para combater os males.</color></size>",
  str_n7_paper_3_4_content = "<size=28><color=#353330>De acordo com os últimos relatórios internos, Rhein, o líder da Blue Lion Guild, uma das mais prósperas da cidade nos últimos anos, parece estar contatando ativamente Istvan em particular, esperando pela coexistência pacífica das duas partes no futuro. Istvan também parece ter respondido de boa vontade.\nEmbora a luta pelo poder entre a Blue Lion Guild e o Guild Headquarters liderado por Istvan tenha promovido a prosperidade e o desenvolvimento em Umbraton, ela também causou objetivamente muitos problemas sociais. Alguns críticos acreditam que este é um passo importante para estabelecer a verdadeira paz em Umbraton, simbolizando a reconciliação entre as novas e velhas forças da cidade.\nAlguns também acreditam que isso é apenas uma cortina de fumaça para os dois lados. Agora estamos testemunhando a calmaria antes da tempestade como uma conspiração ainda maior.</color></size>",
  str_n7_paper_3_5_content = "<size=28><color=#353330>Segundo fontes confiáveis, a família Solus recentemente recrutou tropas em segredo para formar uma equipe profissional especializada em operações secretas e até recrutou Mund, o Stealth King. Há muitos rumores de que o misterioso desaparecimento de muitos dignitários de Umbraton e Lumopolis está inextricavelmente ligado a Mund. Atualmente, vários membros suspeitos de ter um conflito de interesses com organizações comunitárias desapareceram.\nA equipe profissional reunida pela família Solus pode em breve abalar a ordem atual da Umbraton.</color></size>",
  str_n7_paper_4_1_content = "<size=35><color=#353330>A Represa das Cicatrizes foi sabotada. Esta notícia chocante se espalhou por Umbraton e causou grande comoção na cidade. No entanto, podemos relatar com confiança que o culpado por trás da destruição da represa não era outro senão o líder da Blue Lion Guild, Rhein, que já foi levado à justiça pelo fiel protetor de Umbraton, Istvan.\nQuando a inundação que se seguiu avançou em direção a Umbraton, Istvan mais uma vez se manteve firme contra a maré. Ele comandou seus mercenários para drenar e redirecionar a água da região e ajudar os moradores a escapar da zona de perigo. Além disso, Istvan coordenou suas forças com a Cloudrover Guild para resgatar os feridos. Ele então enviou sua gangue para acabar com Solus e seus seguidores, que planejavam usar esta oportunidade para destruir Umbraton. Graças à liderança sábia de Istvan, Umbraton sobreviveu a esta crise com perdas mínimas. Vamos mais uma vez agradecer a Istvan por sua dedicação abnegada a Umbraton.\nQue Istvan continue protegendo Umbraton, agora e para sempre fielmente.\n</color></size>",
  str_n7_paper_4_2_content = "<size=35><color=#353330>É natural torcer pelo azarão. O Caelestite venceu todas as batalhas por vários dias consecutivos. Agora, todos os olhos estão voltados para o último caelestita que avança no torneio, tornando-se um dos jogadores mais populares no campo de batalha. Os torcedores, que se autodenominam \"Lovegators\", cresceram consideravelmente.\nMas vamos nos concentrar agora nos eventos que ocorrem fora da arena. Infelizmente, os torcedores do Celestita têm causado distúrbios nas ruas, envolvendo-se em confrontos frequentes com os torcedores de outros jogadores nos últimos dois dias. Ontem à noite, eles até iniciaram a violência entre a multidão que assistia ao evento, causando caos generalizado. Segundo relatos, o celestita não sabia pessoalmente desses eventos. No entanto, ainda não é difícil perceber que o surgimento do azarão celestita intensificou as diferenças inerentes existentes entre os torcedores. A maioria dos torcedores do Celestita são jovens ansiosos por mudanças, enquanto os torcedores em confronto com eles pertencem à velha escola, ansiosos pelo retorno do atual campeão da arena.\nCom o atrito entre os dois lados já existente há algum tempo, o surgimento do celestita apenas adicionou combustível ao fogo, resultando em um inferno que se prepara para atingir o auge. Até onde esse azarão pode ir? Vamos esperar e ver.</color></size>",
  str_n7_paper_4_3_content = "<size=28><color=#353330>O território controlado pelos ferozes Spearows foi premiado com o Prêmio de Segurança Pública da Umbraton mais uma vez. Quando nosso repórter entrevistou Dayna e Robyn para perguntar-lhes como os Spearows conseguiram prender dezenas de gângsteres de nível de rua todas as semanas, os modestos jovens líderes disseram o seguinte: \"Esses idiotas nas ruas estão sempre tentando machucar Robyn. .. Ei! Você aí! O que você está olhando?!\"\nAgradecemos a Dayna e Robyn por sua excelente contribuição para a segurança da comunidade.</color></size>",
  str_n7_paper_4_4_content = "<size=28><color=#353330>É relatado que Rhein vinha conduzindo secretamente leilões ilegais sob o pretexto de realizar salões frequentes. Nossos repórteres confirmaram que todas as pessoas relacionadas de interesse foram presas.\nEste jornal declara que não tivemos conhecimento dos atos ilegais perpetrados pela Blue Lion Guild. Todos os relatórios relacionados publicados para o salão no passado eram honestos e apenas para fins comerciais. No futuro, todo o conteúdo será monitorado e verificado com mais rigor para evitar a divulgação de informações que possam ter um efeito adverso na sociedade Umbraton.</color></size>",
  str_n7_paper_4_5_content = "<size=28><color=#353330>Um grande número de corpos aprimorados de Eclipsite foi encontrado no beco ao lado do Cornwall Cafe na Cross Street. Um garçom do café nos disse que ouviu um barulho estranho ao fechar ontem à noite. Da vitrine, ela testemunhou um homem musculoso em um uniforme do Lumo Hall of Justice jogando Eclipsites moribundos no beco, um de cada vez.\nEsses corpos agora começaram a se decompor, criando um cheiro forte na área circundante. O homem responsável é instado a entrar em contato com o Umbraton Street Sanitation Office o mais rápido possível para pagar as taxas de descarte correspondentes e multas relacionadas. Caso contrário, a Umbraton não terá escolha a não ser apresentar queixa contra o Lumo Hall of Justice por poluir o meio ambiente.</color></size>",
  str_n7_paper_5_1_content = "<size=35><color=#353330>Acabamos de testemunhar um torneio ferozmente emocionante, graças ao azarão, ou deveríamos dizer, graças ao todo-poderoso Caelestita! Obrigado por nos proporcionar um espetáculo tão incrível!\nObservando os jogos anteriores, comprando informações no mercado negro e espionando, muitos fortes candidatos ao campeonato aprenderam sobre as táticas do celestita. Portanto, diante dos ataques incisivos da equipe celestita, esses contendores não adotaram uma estratégia conservadora e clara, optando por atacar de frente! Após esses ataques selvagens e desesperados, eles pagaram o preço final por sua imprudência e estarão contemplando sua decisão no hospital local!\nSem frustrar as esperanças dos Lovegators! Sem deixar qualquer chance para os adversários! Viva o celestita! Diante das estratégias direcionadas e esquemas insidiosos dos adversários, não houve reclamação sobre suas travessuras ao árbitro. E nosso celestita demonstrou um talento majestoso para táticas e liderança herdado dos grandes comandantes celestitas que já estiveram presentes em Lumopolis, Illumina, Eraveil, Umbraton e Northland. Aproveitando o momento para reivindicar a vitória! A gloriosa tradição dos celestitas!\nVerdadeiramente um em um milhão, nosso celestita possui o poder de perceber oportunidades de ataque que a maioria das pessoas comuns nunca poderia aproveitar em uma vida inteira de batalhas - oportunidades que aparecem uma vez a cada mil anos! Agora, o Celestita não está lutando sozinho - glorioso Navegador, a vitória é sua!\nCom o poder de derrubar inimigos em um golpe decisivo, basta um comando! Um ataque devastador! Deixando os inimigos sem a menor chance de reagir! Com todos na multidão dando testemunho! O Caelestita reivindicou a vitória - não apenas pessoal, mas para os companheiros Caelestitas, a equipe, a Arena Subterrânea, Istvan, Umbraton e todos ao redor do mundo que amam a emoção do combate! Viva o celestita!\n*Gostaríamos de aproveitar esta oportunidade para pedir desculpas a todos os leitores. Há muito tempo não víamos um torneio tão empolgante. Como o repórter que testemunhou a batalha final desmaiou de emoção depois de escrever a reportagem ao vivo acima, o editor-chefe assumiu a responsabilidade de continuar escrevendo este artigo.\nApós a vitória do Caelestite, Istvan presenteou nosso vencedor com um cinturão, representando a supremacia final na Arena Subterrânea, garantindo assim um lugar no hall da fama do Caelestite! Quando o cinto foi levantado, o público explodiu em uma ruidosa salva de palmas. Além disso, os aplausos ressoaram por toda a arena pelo que pareceu uma eternidade.\nTodo-poderoso campeão caelestita, você sempre terá um lugar no coração de todo e qualquer povo de Umbraton!\n</color></size>",
  str_n7_paper_5_2_content = "<size=35><color=#353330>Os leilões clandestinos foram suspensos devido à recente rebelião. Agora foi proibido devido à sua relação inextricável com Rhein. Depois de saber dessa infeliz notícia, tanto os compradores quanto os vendedores clamaram indignados que não teriam mais a oportunidade de obter os raros itens de leilão em oferta nem colher benefícios financeiros desses leilões - um golpe duplo desferido para todos os envolvidos.\nEm meio à desgraça e melancolia em torno da situação, Bethel propôs que a Sede da Guilda de Umbraton revivesse fielmente esses leilões clandestinos. Sim, isso mesmo - um avivamento fiel! Ela prometeu continuar hospedando os leilões, fornecendo um novo local, publicidade e segurança, levando os desanimados compradores e vendedores de Umbraton a finalmente ver a luz da esperança.\nDepois disso, sob a supervisão da Sede da Guilda, o primeiro leilão foi realizado na Praça Umbraton. Como todos ouviram o som ecoante do martelo caindo, o evento foi oficialmente reconhecido como um leilão de superfície. Bethel também anunciou que, a partir daquele dia, o leilão de superfície seria aberto a todos. Todos podem participar, desde que apresentem um pedido na Sede da Guilda e recebam autorização, sem quaisquer condições adicionais! Os envolvidos com os leilões originais choraram de alegria ao ouvir a notícia. Eles aplaudiram a decisão de Bethel e anunciaram que ficariam orgulhosos de participar dos novos leilões de superfície.\nViva o leilão de superfície! Viva o livre comércio! Viva Betel!</color></size>",
  str_n7_paper_5_3_content = "<size=28><color=#353330>Credibilidade sem limites! Poderes de batalha, habilidade e experiência são virtudes que podem ser cultivadas, mas nenhuma virtude é mais difícil de refinar do que a credibilidade. Neste esquadrão de mercenários, você pode confiar com segurança em seus aliados e fazer com que eles o tratem da mesma forma.</color></size>",
  str_n7_paper_5_4_content = "<size=28><color=#353330>Moradores da Cross Street, vocês já ouviram risadas estranhas ecoando pelas ruas tarde da noite? A fonte desse riso foi uma sombra escura recentemente vista à espreita no final da rua. Essa sombra era uma aberração da natureza auroriana? Ou a personificação de nossa moralidade em declínio coletivo? Agora vamos resolver este enigma, exclusivamente para você - esta sombra assombrando Umbraton na calada da noite era, na verdade, ninguém menos que Miller III.\nMiller III, que fez uma aposta extremamente grande na vitória do Caelestite, recentemente perdeu seu investimento devido ao colapso da Blue Lion Guild. Ele também aparentemente sofreu um duro golpe em seu ego e começou a vagar por Umbraton à noite como um espectro inquieto.\nQuando nosso repórter finalmente o encurralou e perguntou como ele se sentia sobre a vitória do celestita, ele de repente gritou e fugiu. Tudo o que nosso repórter conseguiu encontrar dele foi um sapato sem cadarço na beira do rio. Miller III, o herdeiro da guilda centenária, está desaparecido, dado como morto.\nCaçadores de sonhos como ele aparecem em Umbraton todos os dias. Contanto que você possa se adaptar às regras não escritas de Umbraton, este pode ser um lugar feliz. Se não o fizer, um destino infeliz espera por você. Ah, o belo e misterioso Umbraton - um lugar de esperanças, desejos e sonhos sem fim.</color></size>",
  str_n7_paper_5_5_content = "<size=28><color=#353330>Já foi considerado respeitável para os residentes de Umbraton obter uma posição na Guilda do Leão Azul. Agora, a Blue Lion Guild tornou-se objeto de desprezo da cidade. Seus membros abandonaram seus broches outrora orgulhosos e desertaram para se juntar a outras guildas na esperança de sobreviver em Umbraton.\nA família Solus, instigadora do tumulto recente, desapareceu e provavelmente fugiu de Umbraton. Fontes anônimas agora estão oferecendo um alto preço por informações sobre a família Solus. Se você souber seu paradeiro ou estado atual, vivo ou morto, por favor, informe este jornal imediatamente.</color></size>",
  str_n7_integral_contrast = "Honra atual/honra disponível",
  str_n7_recommend_lv = "Nível Médio de Aurorian Recomendado",
  str_n7_activity_lock = "Trancado",
  str_n7_salutation_0 = "Arena recém-chegado",
  str_n7_salutation_450 = "Duelista Novato",
  str_n7_salutation_900 = "Duelista Experiente",
  str_n7_salutation_1800 = "Arena Veterano",
  str_n7_salutation_2700 = "Mestre da Arena",
  str_n7_salutation_3600 = "Duelista Lendário",
  str_n7_activityintro_title = "Inf. do Evento",
  str_n7_activityintro_intro = "<color=#ee8d1a>Obtendo Honra da Arena Subterrânea:</color>\n1. Durante o período do evento, se você participar da Arena Subterrânea, sua maior Honra a cada dia entre os três níveis de dificuldade será calculada como sua Honra final para aquele dia e adicionada à sua Honra Total.\n2. A Underground Arena é atualizada todos os dias. Depois de atualizar, sua Honra da Arena Subterrânea também será atualizada para aquele dia.\n3. Sua Honra na Arena Subterrânea será acumulada todos os dias, e esse valor será registrado como sua Honra Total. As recompensas correspondentes do Caminho para a Glória serão desbloqueadas após acumular uma certa quantidade de Honra Total.\n<color=#ee8d1a> Jogabilidade da Arena Subterrânea:</color>\n1. Na Underground Arena, você enfrentará inimigos que também podem atravessar ladrilhos e usar ataques normais e Chain Combos. Os atributos de ambos os lados serão ajustados automaticamente e o dano de um único ataque causado ao inimigo nunca pode exceder 10% de seu HP máximo.\n2. Existem 3 níveis de dificuldade neste modo, com vários estágios para cada dificuldade. Quanto maior a dificuldade que você selecionar e quanto mais estágios você completar, mais Honra você obterá.\n3. A Underground Arena é atualizada todos os dias. Não há limite para o número de desafios que você pode tentar por dia em cada nível de dificuldade.",
